import{_ as a,o as t,c as o,ao as n}from"./chunks/framework.CiyBIc8J.js";const p=JSON.parse('{"title":"Authors, funding and acknowledgements","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":null}'),r={name:"about.md"};function s(i,e,h,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="Authors,-funding-and-acknowledgements" tabindex="-1">Authors, funding and acknowledgements <a class="header-anchor" href="#Authors,-funding-and-acknowledgements" aria-label="Permalink to &quot;Authors, funding and acknowledgements {#Authors,-funding-and-acknowledgements}&quot;">​</a></h1><h2 id="Authors" tabindex="-1">Authors <a class="header-anchor" href="#Authors" aria-label="Permalink to &quot;Authors {#Authors}&quot;">​</a></h2><p>Sam Abbott, Kath Sherratt, Samuel Brand and Sebastian Funk.</p><p>The model code and analysis were drafted by a language model, then reviewed and revised under human oversight. The named authors are responsible for that oversight. The <a href="./limitations">limitations</a> set out what that means for the work.</p><h2 id="Funding" tabindex="-1">Funding <a class="header-anchor" href="#Funding" aria-label="Permalink to &quot;Funding {#Funding}&quot;">​</a></h2><p>This work was funded by the National Institute for Health and Care Research (NIHR) Health Protection Research Unit in Health Analytics &amp; Modelling, a partnership between the UK Health Security Agency, Imperial College London and the London School of Hygiene &amp; Tropical Medicine (grant code NIHR207404). The views expressed are those of the authors and not necessarily those of the NIHR, UK Health Security Agency or the Department of Health and Social Care.</p><h2 id="Data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#Data-sources" aria-label="Permalink to &quot;Data sources {#Data-sources}&quot;">​</a></h2><p>The DRC counts are taken from the situation reports of the Institut National de Santé Publique (INSP), which are the source of every national, provincial and health-zone series here. The Uganda exports and the deaths among them come from WHO situation reports and Disease Outbreak News. The INRB-UMIE mirror is used to cross-check the scanned INSP totals, not as a source in its own right. We thank the INSP and WHO teams who compile and publish these reports.</p><h2 id="Prior-work-this-builds-on" tabindex="-1">Prior work this builds on <a class="header-anchor" href="#Prior-work-this-builds-on" aria-label="Permalink to &quot;Prior work this builds on {#Prior-work-this-builds-on}&quot;">​</a></h2><p>This work started as a replication of the <a href="/BVDOutbreakSize/dev/references#mccabe2026">McCabe and others (2026)</a> report on the size of the outbreak. It has since grown into a joint model fitted to more of the published data streams. The <a href="./aim">aim and origins</a> page sets out what has changed since the replication. The onset-to-admission and onset-to-death delays come from a Bayesian reanalysis (<a href="/BVDOutbreakSize/dev/references#bdbv_linelist_analysis_2026">Funk and Abbott, 2026</a>) of the line list from the 2012 Bundibugyo outbreak in Isiro (<a href="/BVDOutbreakSize/dev/references#rosello2015">Rosello and others, 2015</a>).</p><h2 id="Citing-this-work" tabindex="-1">Citing this work <a class="header-anchor" href="#Citing-this-work" aria-label="Permalink to &quot;Citing this work {#Citing-this-work}&quot;">​</a></h2><p>The repository carries a <code>CITATION.cff</code> with the current metadata, and each release is archived with a DOI.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Abbott, S., Sherratt, K., Brand, S. and Funk, S.</span></span>
<span class="line"><span>BVDOutbreakSize: estimating the current size of the 2026 DRC Bundibugyo</span></span>
<span class="line"><span>virus outbreak. https://doi.org/10.5281/zenodo.20312758</span></span></code></pre></div><p>The DOI above resolves to the latest release. The <a href="./news">news</a> page records what changed in each one.</p><h2 id="Reuse" tabindex="-1">Reuse <a class="header-anchor" href="#Reuse" aria-label="Permalink to &quot;Reuse {#Reuse}&quot;">​</a></h2><p>The code is MIT licensed. We support reuse and adaptation, and we welcome feedback and corrections through the <a href="https://github.com/epiforecasts/BVDOutbreakSize" target="_blank" rel="noreferrer">repository</a>. The <a href="./contributing">contributing guide</a> covers how to build and extend it.</p>`,16)])])}const b=a(r,[["render",s]]);export{p as __pageData,b as default};
